update public.question_bank
set question_text = 'Duas entidades do setor público realizaram uma fusão, dando origem a uma terceira entidade. Os custos relacionados à fusão referentes a honorários de consultores e auditores independentes e custos de registro foram de R$ 30.000. Ao verificar a situação, um perito constatou que a entidade resultante e as combinações de operações consideraram os custos relacionados à fusão no período em que incorreram, como',
    options = '{"A":"despesa.","B":"ativo intangível.","C":"ativo circulante.","D":"passivo circulante.","E":"passivo não circulante."}'::jsonb,
    explanation = 'A alternativa correta é A — despesa. Em uma fusão, gastos com honorários de consultores, auditores independentes e custos de registro são custos diretamente relacionados à realização da operação. Esses gastos não representam um ativo controlado pela entidade e não geram, por si só, um recurso econômico separado que possa ser reconhecido como ativo intangível. Por isso, devem ser reconhecidos como despesa no período em que a fusão ocorre ou em que o serviço é recebido. O valor de R$ 30.000 não deve ser registrado como ativo circulante nem como passivo. Também não se soma ao custo de um bem específico. A palavra “incorreram” indica o momento do reconhecimento: o gasto é registrado quando o serviço ou obrigação ocorre, respeitando o regime de competência.'
where id = 'afda3b09-0689-4606-a3c0-c3efbbd3817e';
